// путь от корня до target; true, если нашли
bool Path(TreeNode node, TreeNode target, List<TreeNode> path) {
    if (node == null) return false;
    path.Add(node);
    if (node == target || Path(node.left, target, path) || Path(node.right, target, path))
        return true;
    path.RemoveAt(path.Count - 1);   // target не под этим узлом — убираем его
    return false;
}
// LCA — последний общий узел двух путей

